(() => {
  "use strict";
  const $ = (s) => document.querySelector(s),
    $$ = (s) => [...document.querySelectorAll(s)];
  let sound = false,
    ctx;
  const motion = matchMedia("(prefers-reduced-motion: reduce)");
  function tone(notes = [523, 659, 784]) {
    if (!sound) return;
    try {
      ctx = ctx || new (window.AudioContext || window.webkitAudioContext)();
      ctx.resume();
      notes.forEach((f, i) => {
        let o = ctx.createOscillator(),
          g = ctx.createGain(),
          t = ctx.currentTime + i * 0.12;
        o.type = "sine";
        o.frequency.value = f;
        g.gain.setValueAtTime(0, t);
        g.gain.linearRampToValueAtTime(0.065, t + 0.015);
        g.gain.exponentialRampToValueAtTime(0.001, t + 0.35);
        o.connect(g);
        g.connect(ctx.destination);
        o.start(t);
        o.stop(t + 0.4);
      });
    } catch (e) {
      sound = false;
      $("#sound").textContent = "Sound unavailable";
      $("#sound").setAttribute("aria-pressed", "false");
    }
  }
  $("#sound").onclick = () => {
    sound = !sound;
    $("#sound").textContent = sound ? "Sound on" : "Sound off";
    $("#sound").setAttribute("aria-pressed", String(sound));
    tone();
  };
  const stamps = new Set();
  function stamp(name) {
    stamps.add(name);
    $("[data-stamp=" + name + "]").classList.add("done");
    if (stamps.size === 5) {
      $("#progress").textContent =
        "All 5 moments discovered. Passport complete!";
      party();
      tone([523, 659, 784, 1047]);
      buzz([30, 40, 30]);
    } else {
      $("#progress").textContent = stamps.size + " of 5 moments discovered";
    }
  }
  const canvas = $("#confetti"),
    c = canvas.getContext("2d");
  let particles = [],
    running = false;
  function party() {
    if (motion.matches) return;
    canvas.width = innerWidth;
    canvas.height = innerHeight;
    const colors = ["#ecc6d2", "#8ca27b", "#efc76d", "#afa0c7", "#e29473"];
    particles = Array.from({ length: 110 }, () => ({
      x: innerWidth / 2,
      y: innerHeight * 0.55,
      vx: (Math.random() - 0.5) * 15,
      vy: -Math.random() * 12 - 4,
      r: 3 + Math.random() * 4,
      color: colors[Math.floor(Math.random() * colors.length)],
      life: 160,
      rot: Math.random() * 6,
    }));
    if (!running) {
      running = true;
      requestAnimationFrame(draw);
    }
  }
  function draw() {
    c.clearRect(0, 0, canvas.width, canvas.height);
    particles = particles.filter((p) => p.life-- > 0);
    for (const p of particles) {
      p.x += p.vx;
      p.y += p.vy;
      p.vy += 0.12;
      p.rot += 0.08;
      c.save();
      c.globalAlpha = Math.min(1, p.life / 30);
      c.translate(p.x, p.y);
      c.rotate(p.rot);
      c.fillStyle = p.color;
      c.fillRect(-p.r, -p.r, p.r * 1.7, p.r);
      c.restore();
    }
    if (particles.length) requestAnimationFrame(draw);
    else running = false;
  }
  motion.addEventListener("change", () => {
    if (motion.matches) {
      particles = [];
      c.clearRect(0, 0, canvas.width, canvas.height);
    }
  });
  $("#open-gift").onclick = () => {
    $("#open-gift").setAttribute("aria-expanded", "true");
    $("#open-gift").hidden = true;
    $("#gift-message").hidden = false;
    stamp("gift");
    party();
    tone();
  };
  let candles = 0;
  $$(".candle").forEach(
    (b, i) =>
      (b.onclick = () => {
        if (b.classList.contains("out")) return;
        b.classList.add("out");
        b.setAttribute("aria-label", "Candle " + (i + 1) + " extinguished");
        b.disabled = true;
        candles++;
        tone([500 - candles * 30]);
        $("#candle-status").textContent =
          candles === 5
            ? "Wish made. Here's to good things!"
            : 5 - candles + " candles left. Save your wish for the last one.";
        if (candles === 5) {
          stamp("cake");
          party();
          tone([523, 659, 784, 1047]);
        }
      }),
  );
  $("#relight").onclick = () => {
    candles = 0;
    $$(".candle").forEach((b, i) => {
      b.classList.remove("out");
      b.disabled = false;
      b.setAttribute("aria-label", "Blow out candle " + (i + 1));
    });
    $("#candle-status").textContent = "Five candles. One very good wish.";
  };
  const flavours = {
    strawberry: ["#e8a8b5", "#f9d5df"],
    chocolate: ["#ac806c", "#d7ad8a"],
    vanilla: ["#e1c896", "#fff0ce"],
  };
  $$("[data-flavour]").forEach(
    (b) =>
      (b.onclick = () => {
        $$("[data-flavour]").forEach((x) =>
          x.setAttribute("aria-pressed", String(x === b)),
        );
        let [cake, icing] = flavours[b.dataset.flavour];
        $("#cake-art").style.setProperty("--cake", cake);
        $("#cake-art").style.setProperty("--icing", icing);
        tone([440, 554]);
      }),
  );
  $("#sprinkles").onclick = () => {
    let on = $("#cake-art").classList.toggle("sprinkled");
    $("#sprinkles").textContent = on ? "Remove sprinkles −" : "Add sprinkles +";
    $("#sprinkles").setAttribute("aria-pressed", String(on));
  };
  const SCN = {
    1: "data:image/svg+xml;base64,",
    2: "data:image/svg+xml;base64,",
    3: "data:image/svg+xml;base64,",
    4: "data:image/svg+xml;base64,",
    5: "data:image/svg+xml;base64,",
    6: "data:image/svg+xml;base64,",
  };
  const PAIRS = [
    [1, "Sunrise over green hills"],
    [2, "Balloons above the sea"],
    [3, "Birthday cake with candles"],
    [4, "Night sky with lanterns"],
    [5, "Garden of flowers"],
    [6, "City fireworks"],
  ];
  let first = null,
    lock = false,
    pairs = 0,
    moves = 0,
    round = 0;
  function newGame() {
    round++;
    first = null;
    lock = false;
    pairs = 0;
    moves = 0;
    $("#pairs").textContent = "0 / 6";
    $("#moves").textContent = "0";
    $("#game-status").textContent = "Ready when you are.";
    let deck = [...PAIRS, ...PAIRS];
    for (let i = deck.length - 1; i > 0; i--) {
      let j = Math.floor(Math.random() * (i + 1));
      [deck[i], deck[j]] = [deck[j], deck[i]];
    }
    $("#game-board").innerHTML = "";
    deck.forEach(([id, name], i) => {
      let b = document.createElement("button");
      b.className = "game-card";
      b.dataset.name = name;
      b.innerHTML =
        '<span class="back" aria-hidden="true">b.</span><span class="face" aria-hidden="true"><img src="' +
        SCN[id] +
        '" alt="" draggable="false"></span>';
      b.setAttribute("aria-label", "Reveal card " + (i + 1));
      b.onclick = () => {
        if (
          lock ||
          b.classList.contains("revealed") ||
          b.classList.contains("matched")
        )
          return;
        b.classList.add("revealed");
        b.setAttribute("aria-label", "Card " + (i + 1) + ": " + name);
        tone([440]);
        if (!first) {
          first = b;
          return;
        }
        moves++;
        $("#moves").textContent = moves;
        if (first.dataset.name === name) {
          [first, b].forEach((x) => {
            x.classList.add("matched");
            x.disabled = true;
          });
          first = null;
          pairs++;
          $("#pairs").textContent = pairs + " / 6";
          $("#game-status").textContent =
            pairs === 6
              ? "All six found in " + moves + " moves. Birthday champion!"
              : "A match! Keep going.";
          if (pairs === 6) {
            stamp("game");
            party();
            tone([523, 659, 784]);
            bestMoves(moves);
          }
        } else {
          lock = true;
          let old = first,
            r = round;
          $("#game-status").textContent = "So close. Try another two.";
          setTimeout(() => {
            if (r !== round) return;
            [old, b].forEach((x) => {
              x.classList.remove("revealed");
              x.setAttribute(
                "aria-label",
                "Reveal card " +
                  ([...$("#game-board").children].indexOf(x) + 1),
              );
            });
            first = null;
            lock = false;
          }, 950);
        }
      };
      $("#game-board").append(b);
    });
  }
  $("#new-game").onclick = newGame;
  newGame();
  const notes = [
    "May the happy moments be frequent, the laughs be loud, and the cake slices be generous.",
    "May you find the courage to try, the space to learn, and plenty of reasons to be proud of yourself.",
    "May the ordinary days have little bright spots: a good conversation, a good snack, a very good nap.",
    "May today feel easy, cheerful, and completely yours. Happy birthday!",
  ];
  const titles = [
    "For the good days.",
    "For the big dreams.",
    "For the in-between.",
    "For this very day.",
  ];
  const seen = new Set();
  $$("[data-note]").forEach(
    (b) =>
      (b.onclick = () => {
        const i = Number(b.dataset.note),
          open = b.classList.toggle("open");
        b.setAttribute("aria-expanded", String(open));
        b.querySelector("strong").textContent = open ? notes[i] : titles[i];
        b.querySelector("small").textContent = open
          ? "WITH GOOD WISHES / TAP TO TURN BACK"
          : "Turn me over ↗";
        seen.add(i);
        if (seen.size === 4) stamp("notes");
        tone([659, 784]);
      }),
  );
  const SCENES = [
    [
      "data:image/svg+xml;base64,",
      "Illustrated sunrise over rolling green hills",
      "A LITTLE SUNSHINE.",
    ],
    [
      "data:image/svg+xml;base64,",
      "Illustrated balloons floating above the sea",
      "USE THE ARROWS FOR MORE.",
    ],
    [
      "data:image/svg+xml;base64,",
      "Illustrated birthday cake with lit candles",
      "USE THE ARROWS FOR MORE.",
    ],
    [
      "data:image/svg+xml;base64,",
      "Illustrated night sky with glowing lanterns",
      "USE THE ARROWS FOR MORE.",
    ],
    [
      "data:image/svg+xml;base64,",
      "Illustrated garden of pink and yellow flowers",
      "USE THE ARROWS FOR MORE.",
    ],
    [
      "data:image/svg+xml;base64,",
      "Illustrated city skyline with fireworks",
      "USE THE ARROWS FOR MORE.",
    ],
    [
      "data:image/svg+xml;base64,",
      "Illustrated birthday greeting card with balloons and flowers",
      "Another year, another reason to celebrate. Happy birthday!",
    ],
  ];
  let photo = 0;
  const dialog = $("#photo-dialog");
  function showPhoto() {
    const R = SCENES[photo];
    $("#viewer-image").src = R[0];
    $("#viewer-image").alt = R[1];
    $("#viewer-note").textContent = R[2];
    $("#viewer-note").style.textTransform = photo === 6 ? "none" : "";
    $("#prev-photo").disabled = $("#next-photo").disabled = photo === 6;
    $("#viewer-count").textContent =
      photo === 6 ? "The birthday wish" : "Picture " + (photo + 1) + " of 6";
  }
  $$("[data-photo]").forEach(
    (b) =>
      (b.onclick = () => {
        photo = Number(b.dataset.photo);
        showPhoto();
        dialog.showModal();
        document.body.style.overflow = "hidden";
      }),
  );
  $("#prev-photo").onclick = () => {
    if (photo === 6) return;
    photo = (photo + 5) % 6;
    showPhoto();
  };
  $("#next-photo").onclick = () => {
    if (photo === 6) return;
    photo = (photo + 1) % 6;
    showPhoto();
  };
  dialog.querySelector(".close").onclick = () => dialog.close();
  dialog.addEventListener("close", () => (document.body.style.overflow = ""));
  dialog.addEventListener("click", (e) => {
    if (e.target === dialog) {
      let r = dialog.getBoundingClientRect();
      if (
        e.clientX < r.left ||
        e.clientX > r.right ||
        e.clientY < r.top ||
        e.clientY > r.bottom
      )
        dialog.close();
    }
  });
  dialog.addEventListener("keydown", (e) => {
    if (e.key === "ArrowRight") $("#next-photo").click();
    if (e.key === "ArrowLeft") $("#prev-photo").click();
  });
  $("#celebrate").onclick = () => {
    stamp("party");
    party();
    tone([523, 523, 587, 523, 698, 659, 523, 523, 587, 523, 784, 698]);
    $("#party-status").textContent = motion.matches
      ? "HAPPY BIRTHDAY! ALL THE CHEER, WITHOUT THE MOTION."
      : "HAPPY BIRTHDAY! ENCORE? TAP AGAIN.";
  };
  const dockLinks = $$(".mobile-dock a");
  const sectionObserver = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        dockLinks.forEach((a) => {
          if (a.hash === "#" + entry.target.id)
            a.setAttribute("aria-current", "location");
          else a.removeAttribute("aria-current");
        });
      });
    },
    { rootMargin: "-15% 0px -60% 0px" },
  );
  dockLinks.forEach((a) => sectionObserver.observe($(a.hash)));
  /* ---- world4 polish: haptics, birthday tune, best score, reveals ---- */
  function buzz(p) {
    try {
      if (navigator.vibrate) navigator.vibrate(p);
    } catch (e) {}
  }
  $("#open-gift").addEventListener("click", () => buzz(20));
  $$(".candle").forEach((b) => b.addEventListener("click", () => buzz(12)));
  $$("[data-note]").forEach((b) => b.addEventListener("click", () => buzz(10)));
  $$("[data-photo]").forEach((b) =>
    b.addEventListener("click", () => buzz(10)),
  );
  $("#game-board").addEventListener("click", (e) => {
    if (e.target.closest(".game-card")) buzz(8);
  });
  $("#celebrate").addEventListener("click", () => buzz([20, 40, 20, 40, 60]));

  /* birthday tune - full melody, user-triggered, enables sound */
  const melody = [
    [392, 0.75],
    [392, 0.25],
    [440, 1],
    [392, 1],
    [523, 1],
    [494, 1.75],
    [392, 0.75],
    [392, 0.25],
    [440, 1],
    [392, 1],
    [587, 1],
    [523, 1.75],
    [392, 0.75],
    [392, 0.25],
    [784, 1],
    [659, 1],
    [523, 1],
    [494, 1],
    [440, 1.75],
    [698, 0.75],
    [698, 0.25],
    [659, 1],
    [523, 1],
    [587, 1],
    [523, 1.75],
  ];
  function playTune() {
    try {
      ctx = ctx || new (window.AudioContext || window.webkitAudioContext)();
      ctx.resume();
      let t = ctx.currentTime + 0.05;
      const beat = 0.42;
      melody.forEach(([f, d]) => {
        const o = ctx.createOscillator(),
          g = ctx.createGain();
        o.type = "triangle";
        o.frequency.value = f;
        g.gain.setValueAtTime(0, t);
        g.gain.linearRampToValueAtTime(0.09, t + 0.02);
        g.gain.exponentialRampToValueAtTime(0.001, t + d * beat * 0.95);
        o.connect(g);
        g.connect(ctx.destination);
        o.start(t);
        o.stop(t + d * beat);
        t += d * beat;
      });
    } catch (e) {}
  }
  $("#tune").onclick = () => {
    if (!sound) {
      sound = true;
      $("#sound").textContent = "Sound on";
      $("#sound").setAttribute("aria-pressed", "true");
    }
    playTune();
    buzz(15);
    $("#party-status").textContent = "A tune, just for the birthday star.";
  };
  /* best score for the matching game */
  function bestMoves(m) {
    try {
      let b = Number(localStorage.getItem("bw-best")) || 0;
      if (!b || m < b) {
        b = m;
        localStorage.setItem("bw-best", b);
      }
      $("#best").textContent = b;
    } catch (e) {
      $("#best").textContent = m;
    }
  }
  try {
    const b0 = Number(localStorage.getItem("bw-best"));
    if (b0) $("#best").textContent = b0;
  } catch (e) {}
  /* scroll reveals on large containers only, so card hover transforms keep working */
  if (!motion.matches) {
    const ro = new IntersectionObserver(
      (es) => {
        es.forEach((e) => {
          if (e.isIntersecting) {
            e.target.classList.add("in");
            ro.unobserve(e.target);
          }
        });
      },
      { rootMargin: "0px 0px -12% 0px" },
    );
    $$(
      ".hero-copy,.hero-art,.section-head,.map-grid,.passport,.split>div,.cake-stage,.cake-controls,.game-copy,#game-board,.postcards,.scrapbook,.scrap-note,.letter,.finale .wrap",
    ).forEach((el) => {
      el.classList.add("reveal");
      ro.observe(el);
    });
  }

  /* Open the world from a wrapped surprise on every fresh visit. No date check. */
  const door = $("#surprise-door"),
    unwrapWorld = $("#unwrap-world");
  if (door && typeof door.showModal === "function") {
    door.showModal();
    document.body.classList.add("parcel-waiting");
    door.addEventListener("close", () => {
      document.body.classList.remove("parcel-waiting");
      window.scrollTo(0, 0);
      const title = $(".hero h1");
      if (title) {
        title.setAttribute("tabindex", "-1");
        title.focus({ preventScroll: true });
      }
    });
    unwrapWorld.onclick = () => {
      door.close();
      party();
      buzz([20, 40, 30]);
    };
  }
})();
